PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS sessions (credential_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS team_members (team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','member')), token_hash TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, accepted_at TEXT);
CREATE TABLE IF NOT EXISTS connections (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('personal','workspace')), user_id TEXT REFERENCES users(id), workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, provider TEXT NOT NULL, namespace TEXT NOT NULL UNIQUE, server_url TEXT NOT NULL, auth_type TEXT NOT NULL CHECK(auth_type IN ('none','bearer','api_key')), status TEXT NOT NULL CHECK(status IN ('connected','error','paused')), is_demo INTEGER NOT NULL DEFAULT 0, capabilities TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK((scope='personal' AND user_id IS NOT NULL AND workspace_id IS NULL) OR (scope='workspace' AND workspace_id IS NOT NULL AND user_id IS NULL)));
CREATE TABLE IF NOT EXISTS connection_credentials (connection_id TEXT PRIMARY KEY REFERENCES connections(id) ON DELETE CASCADE, encrypted_credentials TEXT NOT NULL, encryption_version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS tools (id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, remote_name TEXT NOT NULL, public_name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, input_schema TEXT NOT NULL, risk_level TEXT NOT NULL CHECK(risk_level IN ('read','write','admin')), enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(connection_id,remote_name));
CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, type TEXT NOT NULL, credential_hash TEXT NOT NULL UNIQUE, token_prefix TEXT NOT NULL, last_used_at TEXT, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE, connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, tool_id TEXT REFERENCES tools(id) ON DELETE CASCADE, subject_type TEXT NOT NULL CHECK(subject_type IN ('user','team','client')), subject_id TEXT NOT NULL, permission TEXT NOT NULL CHECK(permission IN ('none','read','write','admin')));
CREATE UNIQUE INDEX IF NOT EXISTS permissions_unique ON permissions(connection_id,COALESCE(tool_id,''),subject_type,subject_id);
CREATE TABLE IF NOT EXISTS tool_calls (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), workspace_id TEXT, client_id TEXT, client_name TEXT NOT NULL, connection_id TEXT, connection_name TEXT NOT NULL, tool_id TEXT, tool_name TEXT NOT NULL, arguments TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL CHECK(status IN ('success','error','denied')), duration_ms INTEGER NOT NULL, error TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS tool_calls_user ON tool_calls(user_id,created_at);
CREATE INDEX IF NOT EXISTS tool_calls_workspace ON tool_calls(workspace_id,created_at);
CREATE INDEX IF NOT EXISTS tools_connection ON tools(connection_id);
CREATE INDEX IF NOT EXISTS permissions_subject ON permissions(subject_type,subject_id);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
